#ifdef LIMITLESS_X64_UEFI_KERNEL
static u64 g_pe_j6_expected_callback = 0ull;
static u64 g_pe_j6_expected_image_base = 0ull;
static u32 g_pe_j6_expected_pid = 0u;
static u32 g_pe_j6_callback_seen = 0u;
static u32 g_pe_j6_callback_reason = 0u;
static u32 g_pe_j6_callback_order = 0u;
static u32 g_pe_j6_order_counter = 0u;

static u32 pe_j6_tls_callback_dispatch(
    u32 pid,
    u64 callback_va,
    u64 image_base,
    u32 reason,
    u64 reserved,
    void *context)
{
    (void)context;

    ++g_pe_j6_order_counter;
    g_pe_j6_callback_order = g_pe_j6_order_counter;
    g_pe_j6_callback_reason = reason;

    if ((pid == g_pe_j6_expected_pid)
        && (callback_va == g_pe_j6_expected_callback)
        && (image_base == g_pe_j6_expected_image_base)
        && (reason == PE64_TLS_REASON_DLL_PROCESS_ATTACH)
        && (reserved == 0ull))
    {
        g_pe_j6_callback_seen = 1u;
        return PE64_OK;
    }

    return PE64_DENIED;
}
#endif

static void debug_write_char(char character)
{
    outb(0x00E9u, (u8)character);
    serial_write_char(character);
}

static void scaffold_cpu_pause(void)
{
    __asm__ __volatile__("pause");
}

static void kernel_stage_debug_write(const char *text)
{
    if (text == 0)
    {
        return;
    }

    while (*text != '\0')
    {
        debug_write_char(*text);
        ++text;
    }
}

static void kernel_stage_marker(const struct boot_info *boot_info, const char *stage)
{
    kernel_stage_debug_write("[x64] stage ");
    kernel_stage_debug_write(stage);
    debug_write_char('\n');
    (void)display64_write_early_kernel_line(boot_info, stage);
}

static u32 kernel_entry_splash_pixel(const struct boot_info *boot_info, u32 rgb)
{
    u32 red = (rgb >> 16) & 0xFFu;
    u32 green = (rgb >> 8) & 0xFFu;
    u32 blue = rgb & 0xFFu;

    if ((boot_info != 0)
        && (boot_info->framebuffer_format == LIMITLESS_BOOT_FRAMEBUFFER_FORMAT_BGR))
    {
        return (red << 16) | (green << 8) | blue;
    }

    return (blue << 16) | (green << 8) | red;
}

static void kernel_entry_draw_raw_splash(const struct boot_info *boot_info)
{
    volatile u32 *framebuffer;
    u32 row;
    u32 column;
    u32 x;
    u32 y;
    u32 panel_x = 12u;
    u32 panel_y = 42u;
    u32 panel_w = 96u;
    u32 panel_h = 52u;
    u32 bg_pixel;
    u32 mark_pixel;
    static const u8 glyph_l[7] = {
        0x10u, 0x10u, 0x10u, 0x10u, 0x10u, 0x10u, 0x1Fu
    };

    if (boot_info == 0 ||
        boot_info->magic != LIMITLESS_BOOT_INFO_MAGIC ||
        (boot_info->bootstrap_flags & LIMITLESS_BOOT_FLAG_FRAMEBUFFER) == 0u ||
        boot_info->framebuffer_base == 0ull ||
        boot_info->framebuffer_bytes < 4ull ||
        boot_info->framebuffer_width == 0u ||
        boot_info->framebuffer_height == 0u ||
        boot_info->framebuffer_pixels_per_scanline < boot_info->framebuffer_width)
    {
        return;
    }

    if (panel_x >= boot_info->framebuffer_width || panel_y >= boot_info->framebuffer_height)
    {
        return;
    }

    if ((panel_x + panel_w) > boot_info->framebuffer_width)
    {
        panel_w = boot_info->framebuffer_width - panel_x;
    }
    if ((panel_y + panel_h) > boot_info->framebuffer_height)
    {
        panel_h = boot_info->framebuffer_height - panel_y;
    }
    if (panel_w == 0u || panel_h == 0u)
    {
        return;
    }

    framebuffer = (volatile u32 *)(u64)boot_info->framebuffer_base;
    bg_pixel = kernel_entry_splash_pixel(boot_info, 0x0012212Cu);
    mark_pixel = kernel_entry_splash_pixel(boot_info, 0x0046D9A6u);
    for (row = 0u; row < panel_h; ++row)
    {
        for (column = 0u; column < panel_w; ++column)
        {
            u64 pixel_index = ((u64)(panel_y + row) * (u64)boot_info->framebuffer_pixels_per_scanline)
                + (u64)(panel_x + column);
            if (((pixel_index + 1ull) * 4ull) > boot_info->framebuffer_bytes)
            {
                continue;
            }
            framebuffer[pixel_index] = bg_pixel;
        }
    }

    for (row = 0u; row < 7u; ++row)
    {
        for (column = 0u; column < 5u; ++column)
        {
            u32 scale_y;
            u32 scale_x;

            if ((glyph_l[row] & (u8)(1u << (4u - column))) == 0u)
            {
                continue;
            }

            for (scale_y = 0u; scale_y < 5u; ++scale_y)
            {
                for (scale_x = 0u; scale_x < 5u; ++scale_x)
                {
                    u64 pixel_index;
                    x = panel_x + 18u + (column * 6u) + scale_x;
                    y = panel_y + 10u + (row * 6u) + scale_y;
                    if (x >= boot_info->framebuffer_width || y >= boot_info->framebuffer_height)
                    {
                        continue;
                    }
                    pixel_index = ((u64)y * (u64)boot_info->framebuffer_pixels_per_scanline) + (u64)x;
                    if (((pixel_index + 1ull) * 4ull) <= boot_info->framebuffer_bytes)
                    {
                        framebuffer[pixel_index] = mark_pixel;
                    }
                }
            }
        }
    }
}

#ifndef LIMITLESS_X64_UEFI_KERNEL
static void console_scroll_if_needed(void)
{
    u32 row;
    u32 column;

    if (g_console_row < VGA_HEIGHT)
    {
        return;
    }

    for (row = 1u; row < VGA_HEIGHT; ++row)
    {
        for (column = 0u; column < VGA_WIDTH; ++column)
        {
            VGA_BUFFER[(row - 1u) * VGA_WIDTH + column] = VGA_BUFFER[row * VGA_WIDTH + column];
        }
    }

    for (column = 0u; column < VGA_WIDTH; ++column)
    {
        VGA_BUFFER[(VGA_HEIGHT - 1u) * VGA_WIDTH + column] = (u16)' ' | ((u16)g_console_color << 8);
    }

    g_console_row = VGA_HEIGHT - 1u;
}

static void console_write_char(char character)
{
    if (character == '\n')
    {
        g_console_column = 0u;
        ++g_console_row;
        console_scroll_if_needed();
        return;
    }

    VGA_BUFFER[g_console_row * VGA_WIDTH + g_console_column] = (u16)character | ((u16)g_console_color << 8);
    ++g_console_column;

    if (g_console_column >= VGA_WIDTH)
    {
        g_console_column = 0u;
        ++g_console_row;
        console_scroll_if_needed();
    }
}
#endif

static void write_string(const char *text)
{
    while (*text != '\0')
    {
        debug_write_char(*text);
#ifndef LIMITLESS_X64_UEFI_KERNEL
        console_write_char(*text);
#endif
        ++text;
    }
}

static void write_line(const char *text)
{
    write_string(text);
    debug_write_char('\n');
#ifndef LIMITLESS_X64_UEFI_KERNEL
    console_write_char('\n');
#endif
}

static void write_hex_digit(u8 value)
{
    if (value < 10u)
    {
        debug_write_char((char)('0' + value));
#ifndef LIMITLESS_X64_UEFI_KERNEL
        console_write_char((char)('0' + value));
#endif
        return;
    }

    debug_write_char((char)('A' + (value - 10u)));
#ifndef LIMITLESS_X64_UEFI_KERNEL
    console_write_char((char)('A' + (value - 10u)));
#endif
}

static void write_hex_u64(u64 value)
{
    s32 shift;

    write_string("0x");
    for (shift = 60; shift >= 0; shift -= 4)
    {
        write_hex_digit((u8)((value >> shift) & 0x0Full));
    }
}

static void write_hex_u32(u32 value)
{
    s32 shift;

    write_string("0x");
    for (shift = 28; shift >= 0; shift -= 4)
    {
        write_hex_digit((u8)((value >> shift) & 0x0Fu));
    }
}

static void write_dec_u32(u32 value)
{
    char digits[10];
    u32 count = 0u;

    if (value == 0u)
    {
        debug_write_char('0');
#ifndef LIMITLESS_X64_UEFI_KERNEL
        console_write_char('0');
#endif
        return;
    }

    while ((value > 0u) && (count < 10u))
    {
        digits[count++] = (char)('0' + (value % 10u));
        value /= 10u;
    }

    while (count > 0u)
    {
        --count;
        debug_write_char(digits[count]);
#ifndef LIMITLESS_X64_UEFI_KERNEL
        console_write_char(digits[count]);
#endif
    }
}

static void __attribute__((noinline)) write_labeled_hex_u32(const char *label, u32 value)
{
    write_string(label);
    write_hex_u32(value);
}

static void __attribute__((noinline)) write_labeled_dec_u32(const char *label, u32 value)
{
    write_string(label);
    write_dec_u32(value);
}

static void __attribute__((noinline)) write_syscall0_hex_u32(const char *label, u64 call_id)
{
    write_labeled_hex_u32(label, (u32)syscall64_invoke(call_id, 0u, 0u, 0u));
}

static void __attribute__((noinline)) write_syscall0_dec_u32(const char *label, u64 call_id)
{
    write_labeled_dec_u32(label, (u32)syscall64_invoke(call_id, 0u, 0u, 0u));
}

static void __attribute__((noinline)) write_syscall1_hex_u32(const char *label, u64 call_id, u64 arg1)
{
    write_labeled_hex_u32(label, (u32)syscall64_invoke(call_id, arg1, 0u, 0u));
}

static void __attribute__((noinline)) write_syscall1_dec_u32(const char *label, u64 call_id, u64 arg1)
{
    write_labeled_dec_u32(label, (u32)syscall64_invoke(call_id, arg1, 0u, 0u));
}

enum scaffold_telemetry_format
{
    SCAFFOLD_TELEMETRY_DEC = 0u,
    SCAFFOLD_TELEMETRY_HEX = 1u,
    SCAFFOLD_TELEMETRY_HEX64 = 2u
};

struct __attribute__((packed)) scaffold_telemetry_field
{
    const char *suffix;
    u8 selector : 7;
    u8 format : 1;
};

struct __attribute__((packed)) scaffold_arg_telemetry_field
{
    const char *suffix;
    u8 offset;
    u8 format;
};

struct __attribute__((packed)) scaffold_syscall0_field
{
    u16 label_offset;
    u16 call_id;
    u8 format;
};

static void __attribute__((noinline)) write_formatted_u64(u64 value, u8 format)
{
    if (format == SCAFFOLD_TELEMETRY_HEX64)
    {
        write_hex_u64(value);
        return;
    }

    if (format == SCAFFOLD_TELEMETRY_HEX)
    {
        write_hex_u32((u32)value);
        return;
    }

    write_dec_u32((u32)value);
}

static void __attribute__((noinline)) write_syscall0_prefixed_label_fields(
    const char *prefix,
    const char *suffixes,
    const struct scaffold_syscall0_field *fields,
    u32 field_count)
{
    u32 index;

    for (index = 0u; index < field_count; ++index)
    {
        write_string(prefix);
        write_string(suffixes + fields[index].label_offset);
        write_formatted_u64(syscall64_invoke((u64)fields[index].call_id, 0u, 0u, 0u), fields[index].format);
    }
}



