static void wait_for_timer_ticks(u32 target_ticks)
{
    u32 guard = 0u;

    while ((pit_get_ticks() < target_ticks)
        && (guard < SCAFFOLD_TIMER_WAIT_SPIN_BUDGET))
    {
        scaffold_cpu_pause();
        ++guard;
    }
    if (pit_get_ticks() < target_ticks)
    {
        serial_write_string("[x64] bounded timer wait expired\n");
    }
}

static void collect_keyboard_probe_input(u32 target_pending, u32 max_wait_ticks)
{
    u32 target_ticks = pit_get_ticks() + max_wait_ticks;
    u32 guard = 0u;

    interrupts64_enable();
    while ((input64_keyboard_pending_count() < target_pending)
        && (pit_get_ticks() < target_ticks)
        && (guard < SCAFFOLD_KEYBOARD_WAIT_SPIN_BUDGET))
    {
        input64_poll_keyboard();
        xhci64_poll_keyboard();
        scaffold_cpu_pause();
        ++guard;
    }
    interrupts64_disable();
    input64_poll_keyboard();
    xhci64_poll_keyboard();
}

static void collect_mouse_probe_input(u32 target_packets, u32 max_wait_ticks)
{
    u32 target_ticks = pit_get_ticks() + max_wait_ticks;
    u32 guard = 0u;
    u32 xhci_live_polling = xhci64_live_polling_supported();

    if (xhci_live_polling != 0u)
    {
        xhci64_set_live_polling_enabled(1u);
    }
    else
    {
        serial_write_string("[x64] mouse probe using ps2/i2c polling\n");
    }

    interrupts64_enable();
    while ((input64_mouse_packet_count() < target_packets)
        && (pit_get_ticks() < target_ticks)
        && (guard < SCAFFOLD_MOUSE_WAIT_SPIN_BUDGET))
    {
        if ((guard & 0x3Fu) == 0u)
        {
            input64_poll_mouse();
        }
        if (xhci_live_polling != 0u)
        {
            xhci64_poll_mouse();
        }
        scaffold_cpu_pause();
        ++guard;
    }
    interrupts64_disable();
    input64_poll_mouse();
    if (xhci_live_polling != 0u)
    {
        xhci64_poll_mouse();
        xhci64_set_live_polling_enabled(0u);
    }
}

static void collect_gui_interactive_probe_input(u32 max_wait_ticks)
{
    u32 target_ticks = pit_get_ticks() + max_wait_ticks;
    u32 guard = 0u;

    interrupts64_enable();
    while (((display64_gui_launcher_opened() == 0u)
            || (display64_gui_terminal_opened() == 0u)
            || (display64_gui_drag_completed() == 0u)
            || (display64_gui_keyboard_routed() == 0u)
            || (display64_gui_close_completed() == 0u)
            || (display64_gui_taskbar_focus() == 0u)
            || (display64_gui_fileman_opened() == 0u)
            || (display64_gui_settings_opened() == 0u)
            || (display64_gui_installer_opened() == 0u)
            || (display64_gui_assistant_opened() == 0u)
            || (display64_gui_unfocused_key_denied() == 0u))
        && (pit_get_ticks() < target_ticks)
        && (guard < SCAFFOLD_TIMER_WAIT_SPIN_BUDGET))
    {
        input64_poll_keyboard();
        xhci64_poll_keyboard();
        input64_poll_mouse();
        xhci64_poll_mouse();
        scaffold_cpu_pause();
        ++guard;
    }
    interrupts64_disable();
    input64_poll_keyboard();
    xhci64_poll_keyboard();
    input64_poll_mouse();
    xhci64_poll_mouse();
}

static int boot_info_is_valid_x64(const struct boot_info *boot_info)
{
    u32 required_flags = LIMITLESS_BOOT_FLAG_PROTECTED_MODE |
                         LIMITLESS_BOOT_FLAG_LONG_MODE |
                         LIMITLESS_BOOT_FLAG_PAGING |
                         LIMITLESS_BOOT_FLAG_IDENTITY_MAP |
                         LIMITLESS_BOOT_FLAG_HIGH_HALF_ALIAS;

    if ((boot_info == 0) || (boot_info->magic != LIMITLESS_BOOT_INFO_MAGIC))
    {
        return 0;
    }

    if (boot_info->architecture_bits != 64u)
    {
        return 0;
    }

    if ((boot_info->bootstrap_flags & required_flags) != required_flags)
    {
        return 0;
    }

    if ((boot_info->page_table_root == 0u) || (boot_info->identity_map_bytes == 0u))
    {
        return 0;
    }

    return 1;
}

static u32 scaffold_wide_panel_hardware_path(const struct boot_info *boot_info)
{
    return (boot_info_has_framebuffer(boot_info)
        && (boot_info->framebuffer_width >= 1600u))
        ? 1u
        : 0u;
}

#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
static u32 g_boot_diag64_timing_ticks[BOOT_DIAG64_TIMING_COUNT];

static void record_boot_duration_ticks(u32 index, const char *label, u32 start_ticks)
{
    u32 duration_ticks = (u32)(pit_get_ticks() - start_ticks);

    if (index < BOOT_DIAG64_TIMING_COUNT)
    {
        g_boot_diag64_timing_ticks[index] = duration_ticks;
    }

    write_string("[x64] boot-time ");
    write_string(label);
    write_string(" ticks ");
    write_dec_u32(duration_ticks);
    write_line("");
}

u32 boot_diag64_timing_ticks(u32 index)
{
    if (index >= BOOT_DIAG64_TIMING_COUNT)
    {
        return 0u;
    }

    return g_boot_diag64_timing_ticks[index];
}

u32 boot_diag64_timer_wait_spin_budget(void)
{
    return SCAFFOLD_TIMER_WAIT_SPIN_BUDGET;
}
#endif

static void log_build_profile_surface(void)
{
    write_string("[x64] build-profile ");
    write_string(LIMITLESS_BUILD_PROFILE_NAME);
    write_labeled_dec_u32(" product ", LIMITLESS_BUILD_PROFILE_PRODUCT);
    write_labeled_dec_u32(" experimental ", LIMITLESS_BUILD_PROFILE_EXPERIMENTAL);
    write_labeled_dec_u32(" experimental-runtime ", LIMITLESS_EXPERIMENTAL_RUNTIME_ENABLED);
    write_line("");

#if LIMITLESS_EXPERIMENTAL_RUNTIME_ENABLED
    write_line("[x64] experimental-runtime enabled proof-surface 1 not-product-path 1");
#else
    write_line("[x64] experimental-runtime disabled proof-surface 0 gui product-gated network product-gated ai unavailable installer unavailable package-manager unavailable");
#endif
}

void kernel_main64_scaffold(const struct boot_info *boot_info)
{
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    u32 boot_timer_start_ticks = 0u;
    u32 boot_stage_start_ticks = 0u;
#endif

    serial_init();
    kernel_entry_draw_raw_splash(boot_info);
    kernel_stage_marker(boot_info, "KERNEL ENTRY FB ALIVE");
    write_line(g_x64_scaffold_name);

    if (!boot_info_is_valid_x64(boot_info))
    {
        write_line("[boot] invalid x64 boot information");
        for (;;)
        {
            cpu_halt();
        }
    }

    if (boot_info_has_framebuffer(boot_info))
    {
        input64_set_mouse_bounds(
            boot_info->framebuffer_width,
            boot_info->framebuffer_height);
    }

    paging64_configure_kernel_physical_base(boot_info->kernel_load_address);
    serial_write_string("[x64] stage paging active\n");
    log_boot_memory(boot_info);
    log_build_profile_surface();
    services64_init();
    descriptors64_init();
    kernel_stage_marker(boot_info, "GDT OK");
    log_bootstrap_state(boot_info);
    write_line("[x64] long mode active");
    log_framebuffer_handoff(boot_info);
    write_line("");
    write_line("[x64] initializing interrupts");
    interrupts64_init();
    kernel_stage_marker(boot_info, "IDT OK");
    write_line("[x64] IDT online");
    kernel_stage_marker(boot_info, "APIC INIT");
    apic64_init(boot_info);
    kernel_stage_marker(boot_info, "APIC OK");
    if (apic64_enabled() != 0u)
    {
        write_line("[x64] APIC ready");
    }
    else
    {
        pic_initialize(0xF8u, 0xEFu);
        write_line("[x64] PIC ready");
    }
    kernel_stage_marker(boot_info, "PIC MASK");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    write_string("[x64] irq route apic ");
    write_dec_u32(apic64_enabled());
    write_string(" pic-disabled ");
    write_dec_u32(apic64_pic_disabled());
    write_string(" timer-gsi ");
    write_dec_u32(apic64_timer_gsi());
    write_string(" keyboard-gsi ");
    write_dec_u32(apic64_keyboard_gsi());
    write_string(" mouse-gsi ");
    write_dec_u32(apic64_mouse_gsi());
    write_line("");
    kernel_stage_marker(boot_info, "PIT INIT");
#endif
    pit_initialize(100u);
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_timer_start_ticks = pit_get_ticks();
    kernel_stage_marker(boot_info, "PIT OK");
#endif
    write_line("[x64] PIT at 100 Hz");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    kernel_stage_marker(boot_info, "SYSCALL INIT");
#endif
    syscall64_init(boot_info);
    syscall64_native_init();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    kernel_stage_marker(boot_info, "SYSCALL OK");
#endif
    log_descriptor_surface();
    log_bootstrap_catalog();
    log_principal_namespace();
    log_process_namespace();
    log_launch_namespace();
    log_service_namespace();
    write_string("[x64] page root ");
    write_hex_u32(boot_info->page_table_root);
    write_line("");
    log_identity_map(boot_info);
    log_runtime_mapping();
    log_higher_half_alias();
    log_kernel_load(boot_info);
    write_string("[x64] bootstrap kind ");
    write_line(g_x64_scaffold_bootstrap_kind);
    write_string("[x64] paging levels ");
    write_dec_u32(g_x64_scaffold_report.page_levels);
    write_line("");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    kernel_stage_marker(boot_info, "INT PROBES");
#endif
    interrupts64_trigger_probe();
    interrupts64_trigger_breakpoint_proof();
    interrupts64_trigger_invalid_opcode_proof();
    interrupts64_trigger_page_fault_proof();
    interrupts64_trigger_syscall_probe(1u);
    run_user_entry_transfer_probe();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    kernel_stage_marker(boot_info, "INT PROBES OK");
#endif
    kernel_stage_marker(boot_info, "XHCI PROBE");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    xhci64_init();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_XHCI_INIT, "xhci-init", boot_stage_start_ticks);
#endif
    if (scaffold_wide_panel_hardware_path(boot_info) != 0u)
    {
        write_line("[x64] xhci native init complete; lpss i2c hid path remains enabled");
    }
    else
    {
        write_line("[x64] xhci native init complete");
    }
    kernel_stage_marker(boot_info, "XHCI OK");
    xhci64_set_live_polling_enabled(0u);
    kernel_stage_marker(boot_info, "BOOT DIAG");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    (void)display64_write_boot_diagnostics(
        xhci64_found(),
        xhci64_legacy_handoff(),
        xhci64_usb2_ports(),
        xhci64_hid_device(),
        xhci64_error(),
        pci64_usb_uhci_count(),
        pci64_usb_ohci_count(),
        pci64_usb_ehci_count(),
        pci64_usb_xhci_count(),
        input64_ps2_present(),
        input64_ps2_enabled(),
        input64_ps2_scanning_enabled(),
        input64_ps2_status_snapshot(),
        input64_ps2_config_byte(),
        input64_ps2_device_ack(),
        input64_keyboard_scancode_count(),
        input64_keyboard_pending_count(),
        input64_keyboard_last_scancode(),
        pci64_lpss_i2c_hid_found());
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_BOOT_DIAG, "boot-diag", boot_stage_start_ticks);
#endif
    kernel_stage_marker(boot_info, "BOOT DIAG OK");
    kernel_stage_marker(boot_info, "NVME PROBE");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    log_pci_storage_surface();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_NVME_PROBE, "nvme-probe", boot_stage_start_ticks);
#endif
    kernel_stage_marker(boot_info, "NVME OK");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    display64_init(boot_info);
    input64_set_mouse_bounds(display64_width(), display64_height());
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_DISPLAY_INIT, "display-init", boot_stage_start_ticks);
#endif
    kernel_stage_marker(boot_info, "FB INIT");
    kernel_stage_marker(boot_info, "I2C HID INIT");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    i2c_hid64_init();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_I2C_HID_INIT, "i2c-hid-init", boot_stage_start_ticks);
#endif
    write_line("[x64] i2c hid native init complete");
    kernel_stage_marker(boot_info, "I2C HID OK");
    kernel_stage_marker(boot_info, "INPUT PROBE");
    write_line("[x64] input devices ready");
    kernel_stage_marker(boot_info, "USER PREEMPT");
    run_user_entry_preempt_probe();
    kernel_stage_marker(boot_info, "USER PREEMPT OK");
    kernel_stage_marker(boot_info, "USER SWITCH");
    run_user_entry_switch_probe();
    kernel_stage_marker(boot_info, "USER SWITCH OK");
    kernel_stage_marker(boot_info, "USER RUNQUEUE");
    run_user_entry_runqueue_probe();
    kernel_stage_marker(boot_info, "USER RUNQUEUE OK");
    interrupts64_enable();
    kernel_stage_marker(boot_info, "TIMER WAIT");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    wait_for_timer_ticks(30u);
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_TIMER_WAIT, "timer-wait", boot_stage_start_ticks);
#endif
    interrupts64_disable();
    kernel_stage_marker(boot_info, "TIMER OK");
    input64_poll_keyboard();
    kernel_stage_marker(boot_info, "KEYBOARD WAIT");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    collect_keyboard_probe_input(1u, 20u);
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_KEYBOARD_WAIT, "keyboard-wait", boot_stage_start_ticks);
#endif
    if (input64_keyboard_pending_count() == 0u)
    {
        serial_write_string("[x64] keyboard probe optional: no key observed\n");
        kernel_stage_marker(boot_info, "KEYBOARD OPTIONAL");
    }
    else
    {
        kernel_stage_marker(boot_info, "KEYBOARD OK");
    }
    kernel_stage_marker(boot_info, "MOUSE WAIT");
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
#endif
    collect_mouse_probe_input(1u, 20u);
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_MOUSE_WAIT, "mouse-wait", boot_stage_start_ticks);
#endif
    if (input64_mouse_packet_count() == 0u)
    {
        serial_write_string("[x64] mouse probe optional: no packet observed\n");
        kernel_stage_marker(boot_info, "MOUSE OPTIONAL");
    }
    else
    {
        kernel_stage_marker(boot_info, "MOUSE OK");
    }
    (void)display64_write_boot_diagnostics(
        xhci64_found(),
        xhci64_legacy_handoff(),
        xhci64_usb2_ports(),
        xhci64_hid_device(),
        xhci64_error(),
        pci64_usb_uhci_count(),
        pci64_usb_ohci_count(),
        pci64_usb_ehci_count(),
        pci64_usb_xhci_count(),
        input64_ps2_present(),
        input64_ps2_enabled(),
        input64_ps2_scanning_enabled(),
        input64_ps2_status_snapshot(),
        input64_ps2_config_byte(),
        input64_ps2_device_ack(),
        input64_keyboard_scancode_count(),
        input64_keyboard_pending_count(),
        input64_keyboard_last_scancode(),
        pci64_lpss_i2c_hid_found());
    (void)display64_write_mouse_diagnostics(
        input64_ps2_mouse_init_done(),
        input64_ps2_mouse_aux_enabled(),
        input64_ps2_mouse_config_read(),
        input64_ps2_mouse_config_write(),
        input64_ps2_mouse_irq12_configured(),
        input64_ps2_mouse_enable_command(),
        input64_ps2_mouse_ack(),
        input64_mouse_irq_count(),
        input64_mouse_packet_count(),
        input64_mouse_pending_count(),
        input64_mouse_x(),
        input64_mouse_y(),
        input64_mouse_buttons(),
        input64_ps2_mouse_raw_byte(),
        input64_ps2_mouse_bad_start_count(),
        xhci64_keyboard_endpoint_present(),
        xhci64_keyboard_transfer_pending(),
        xhci64_report_count(),
        xhci64_mouse_endpoint_present(),
        xhci64_mouse_transfer_pending(),
        xhci64_mouse_reports(),
        xhci64_live_polling_enabled(),
        i2c_hid64_device_found(),
        i2c_hid64_report_count(),
        i2c_hid64_error(),
        i2c_hid64_pointer_found(),
        i2c_hid64_pointer_report_count(),
        i2c_hid64_pointer_error());
    log_interrupt_probes();
    write_string("[x64] timer ticks ");
    write_dec_u32(pit_get_ticks());
    write_line("");
    log_syscall_surface();
    log_principal_surface();
    log_process_surface();
    log_launch_surface();
    log_service_surface();
    log_input_keyboard_surface();
    log_mouse_surface();
    log_block_surface();
    kernel_stage_marker(boot_info, "INPUT OK");
    kernel_stage_marker(boot_info, "XHCI LIVE");
    xhci64_set_live_polling_enabled(1u);
    kernel_stage_marker(boot_info, "XHCI LIVE OK");
#if LIMITLESS_EXPERIMENTAL_RUNTIME_ENABLED || LIMITLESS_BUILD_PROFILE_PRODUCT
    display64_compositor_probe(input64_mouse_x(), input64_mouse_y(), input64_mouse_buttons());
#endif
    log_compositor_surface();
#if LIMITLESS_EXPERIMENTAL_RUNTIME_ENABLED || LIMITLESS_BUILD_PROFILE_PRODUCT
    display64_font_probe();
#endif
    log_font_surface();
#if LIMITLESS_BUILD_PROFILE_PRODUCT && defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    kernel_stage_marker(boot_info, "LOGIN");
    boot_stage_start_ticks = pit_get_ticks();
    input64_clear_keyboard_pending();
    serial_write_string("[x64] pre-login keyboard probe buffer cleared\n");
    if (auth64_run_login_gate() == 0u)
    {
        write_line("[x64] login gate failed");
        cpu_halt_forever();
    }
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_LOGIN, "login", boot_stage_start_ticks);
    kernel_stage_marker(boot_info, "LOGIN OK");
    boot_stage_start_ticks = pit_get_ticks();
    auth64_controlled_lock_probe();
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_LOCK_PROBE, "lock-probe", boot_stage_start_ticks);
#endif
    log_login_surface();
#if LIMITLESS_EXPERIMENTAL_RUNTIME_ENABLED || LIMITLESS_BUILD_PROFILE_PRODUCT
 #if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
 #endif
    display64_wm_probe();
 #if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_WM_PROBE, "wm-probe", boot_stage_start_ticks);
 #endif
#endif
    log_window_manager_surface();
#if LIMITLESS_EXPERIMENTAL_RUNTIME_ENABLED || LIMITLESS_BUILD_PROFILE_PRODUCT
 #if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
 #endif
    display64_desktop_probe();
 #if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_DESKTOP_PROBE, "desktop-probe", boot_stage_start_ticks);
 #endif
    if (display64_desktop_init_done() != 0u)
    {
        if (scaffold_wide_panel_hardware_path(boot_info) == 0u)
        {
            write_line("[x64] gui interactive input wait");
            collect_gui_interactive_probe_input(6000u);
            log_mouse_surface();
        }
        else
        {
            write_line("[x64] gui interactive input wait skipped on hardware path");
        }
    }
#endif
    log_desktop_surface();
    log_gui_interactive_surface();
    log_input_keyboard_surface();
    log_service_session_surface();
    log_package_signing_surface();
    log_package_trust_status_surface();
    log_identity_surface();
    log_identity_transport_surface();
    log_account_association_surface();
    log_cloud_storage_surface();
    log_installer_ux_surface();
    log_ai_policy_surface();
    log_ai_assistant_surface();
    log_hardware_validation_surface();
    (void)display64_write_mouse_diagnostics(
        input64_ps2_mouse_init_done(),
        input64_ps2_mouse_aux_enabled(),
        input64_ps2_mouse_config_read(),
        input64_ps2_mouse_config_write(),
        input64_ps2_mouse_irq12_configured(),
        input64_ps2_mouse_enable_command(),
        input64_ps2_mouse_ack(),
        input64_mouse_irq_count(),
        input64_mouse_packet_count(),
        input64_mouse_pending_count(),
        input64_mouse_x(),
        input64_mouse_y(),
        input64_mouse_buttons(),
        input64_ps2_mouse_raw_byte(),
        input64_ps2_mouse_bad_start_count(),
        xhci64_keyboard_endpoint_present(),
        xhci64_keyboard_transfer_pending(),
        xhci64_report_count(),
        xhci64_mouse_endpoint_present(),
        xhci64_mouse_transfer_pending(),
        xhci64_mouse_reports(),
        xhci64_live_polling_enabled(),
        i2c_hid64_device_found(),
        i2c_hid64_report_count(),
        i2c_hid64_error(),
        i2c_hid64_pointer_found(),
        i2c_hid64_pointer_report_count(),
        i2c_hid64_pointer_error());
    log_apic_surface();
    log_usb_hci_surface();
    log_xhci_surface();
 #if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    boot_stage_start_ticks = pit_get_ticks();
 #endif
    virtio_net64_init();
 #if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_VIRTIO_NET_INIT, "virtio-net-init", boot_stage_start_ticks);
 #endif
    log_virtio_net_surface();
    log_e1000_surface();
    log_dhcp_surface();
    log_dns_surface();
    log_http_surface();
    log_filesystem_surface();
    log_capability_surface();
    log_fault_surface();
    log_native_syscall_surface();
    log_native_principal_surface();
    log_native_process_surface();
    log_native_launch_surface();
    log_native_service_surface();
    log_native_capability_surface();
    log_native_fault_surface();
    log_network_socket_surface();
    log_brokered_keyboard_read_probe();
    run_user_entry_filesystem_probe();
    log_nvme_rw_surface();
    log_installer_commit_surface();
    log_installer_target_surface();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    log_ai_action_surface();
#endif
    run_user_entry_second_page_probe();
    run_drs_load_probe();
    run_drs_load_full_probe();
    run_app_model_m20_probe();
#if defined(LIMITLESS_X64_UEFI_KERNEL) && LIMITLESS_X64_UEFI_KERNEL
    record_boot_duration_ticks(BOOT_DIAG64_TIMING_PIT_TO_SHELL, "pit-to-shell", boot_timer_start_ticks);
#endif
    write_string("[x64] active virtual ");
    write_hex_u64(g_x64_scaffold_report.active_virtual_base);
    write_line("");
    write_string("[x64] planned high half ");
    write_hex_u64(g_x64_scaffold_report.planned_virtual_base);
    write_line("");
    write_string("[x64] plan ");
    write_line(g_x64_scaffold_plan);
    write_line("[x64] compat32 lane planned");
    kernel_stage_marker(boot_info, "SHELL");
    write_line("[x64] shell ready");
    write_line("[x64] bootstrap halt");
    if (run_persistent_ring3_shell() == 0)
    {
        run_live_keyboard_console();
    }

    for (;;)
    {
        cpu_halt();
    }
}
#endif /* LIMITLESS_SCAFFOLD_CORE_NATIVE_AND_ENTRY */

